package com.alsafa.native4;

import android.app.Activity;import android.text.InputType;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.AccountingChoices;import com.alsafa.native4.core.DirectRepairPartSaleStore;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;import com.alsafa.native4.core.SplitPaymentStore;import java.util.ArrayList;import java.util.List;
/** Quick repair: immediate handover is a paid direct operation; leaving the watch creates an open repair and only reserves parts. */
public final class DirectPartSalePanelBinder {
 private final Activity a;private final Native4Services services;private final TextView status,paymentLabel;private final LinearLayout panel,paymentSection,leaveDetails;private final EditText partId,quantity,unitPrice,serviceFee,customerName,customerPhone,watchNote;private final Spinner currency,handover;
 public DirectPartSalePanelBinder(Activity a,Native4Services services,TextView status,ViewGroup host){this.a=a;this.services=services;this.status=status;panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setVisibility(View.GONE);TextView title=new TextView(a);title.setText("الصيانة السريعة");title.setTextSize(20);title.setGravity(Gravity.END);panel.addView(title);TextView help=new TextView(a);help.setText("اختر القطعة والكمية. إذا استلم العميل الساعة فورًا يتم التحصيل، وإذا تركها لدينا تُفتح صيانة بلا قبض وتُحجز القطعة حتى التسليم.");help.setGravity(Gravity.END);panel.addView(help);partId=field(a,"معرف / باركود قطعة الصيانة",InputType.TYPE_CLASS_TEXT);quantity=field(a,"الكمية",InputType.TYPE_CLASS_NUMBER);quantity.setText("1");unitPrice=field(a,"سعر القطعة للعميل",numType());serviceFee=field(a,"أجرة الخدمة (اختياري)",numType());currency=new Spinner(a);currency.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));panel.addView(partId);panel.addView(quantity);LinearLayout amountRow=new LinearLayout(a);amountRow.setOrientation(LinearLayout.HORIZONTAL);amountRow.addView(unitPrice,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,3f));amountRow.addView(currency,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));panel.addView(amountRow);panel.addView(serviceFee);handover=new Spinner(a);handover.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"تم التسليم — استلم العميل الساعة فورًا","ترك الساعة لدينا — بدون تحصيل الآن"}));panel.addView(handover);leaveDetails=new LinearLayout(a);leaveDetails.setOrientation(LinearLayout.VERTICAL);customerName=field(a,"اسم العميل",InputType.TYPE_CLASS_TEXT);customerPhone=field(a,"رقم الهاتف",InputType.TYPE_CLASS_PHONE);watchNote=field(a,"وصف الساعة / سبب تركها",InputType.TYPE_CLASS_TEXT);leaveDetails.addView(customerName);leaveDetails.addView(customerPhone);leaveDetails.addView(watchNote);leaveDetails.setVisibility(View.GONE);panel.addView(leaveDetails);paymentSection=new LinearLayout(a);paymentSection.setOrientation(LinearLayout.VERTICAL);paymentLabel=new TextView(a);paymentLabel.setText("الدفعات — مبلغ وعملة ومكان التحصيل");paymentLabel.setGravity(Gravity.END);paymentSection.addView(paymentLabel);Button add=new Button(a);add.setText("+ إضافة دفعة أخرى");add.setOnClickListener(v->addPaymentRow());paymentSection.addView(add);panel.addView(paymentSection);addPaymentRow();handover.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){boolean left=pos==1;leaveDetails.setVisibility(left?View.VISIBLE:View.GONE);paymentSection.setVisibility(left?View.GONE:View.VISIBLE);}public void onNothingSelected(android.widget.AdapterView<?> p){}});Button save=new Button(a);save.setText("✓ تثبيت الصيانة السريعة");save.setMinHeight(dp(62));save.setOnClickListener(v->save());panel.addView(save);host.addView(panel);}
 public void show(boolean visible){panel.setVisibility(visible?View.VISIBLE:View.GONE);}
 private void addPaymentRow(){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);EditText amount=field(a,"المبلغ المقبوض",numType());Spinner cur=new Spinner(a);cur.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));Spinner account=new Spinner(a);account.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"الدرج","شام كاش","الخزنة الخارجية","البنك"}));Button remove=new Button(a);remove.setText("حذف الدفعة");remove.setOnClickListener(v->{if(paymentSection.getChildCount()>3)paymentSection.removeView(box);else amount.setText("");});box.addView(amount);box.addView(cur);box.addView(account);box.setTag(new PaymentViews(amount,cur,account));box.addView(remove);paymentSection.addView(box,paymentSection.getChildCount()-1);}
 private List<SplitPaymentStore.Payment> readPayments(){List<SplitPaymentStore.Payment> out=new ArrayList<>();for(int i=0;i<paymentSection.getChildCount();i++){View v=paymentSection.getChildAt(i);if(!(v.getTag() instanceof PaymentViews))continue;PaymentViews p=(PaymentViews)v.getTag();String raw=p.amount.getText().toString().trim();if(raw.isEmpty())continue;double amount=Double.parseDouble(raw);String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,p.currency.getSelectedItemPosition());String acc=accountCode(p.account.getSelectedItemPosition());if("SHAM_CASH".equals(acc)&&"TRY".equals(cur))throw new IllegalArgumentException("شام كاش يقبل الدولار والليرة السورية فقط");out.add(new SplitPaymentStore.Payment(amount,cur,"SHAM_CASH".equals(acc)?"SHAM_CASH":"CASH",acc));}return out;}
 private void save(){try{boolean left=handover.getSelectedItemPosition()==1;String pid=partId.getText().toString().trim();if(pid.isEmpty())throw new IllegalArgumentException("قطعة الصيانة مطلوبة");int q=Integer.parseInt(quantity.getText().toString().trim());if(q<=0)throw new IllegalArgumentException("الكمية غير صالحة");double price=num(unitPrice),fee=num(serviceFee),agreed=price*q+fee;String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,currency.getSelectedItemPosition());if(left){String name=customerName.getText().toString().trim(),phone=customerPhone.getText().toString().trim(),note=watchNote.getText().toString().trim();if(name.isEmpty())throw new IllegalArgumentException("اسم العميل مطلوب عند ترك الساعة لدينا");if(phone.isEmpty())throw new IllegalArgumentException("رقم الهاتف مطلوب عند ترك الساعة لدينا");String desc=note.isEmpty()?"صيانة سريعة — قطعة "+pid:note;String repairId=services.repairs.receive(name,phone,desc,agreed,cur,"LATER");try{services.repairPartReservations.reserve(repairId,pid,q);}catch(Exception reserveError){throw new IllegalStateException("تم إنشاء الصيانة لكن تعذر حجز القطعة: "+msg(reserveError));}Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();reset();status.setText("✓ تم ترك الساعة لدينا — لا يوجد تحصيل الآن — تم حجز القطعة للصيانة "+repairId);return;}List<SplitPaymentStore.Payment> payments=readPayments();DirectRepairPartSaleStore.Result r=services.directPartSales.sellSplit(pid,q,price,fee,cur,payments);Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();reset();status.setText("✓ تم التسليم فورًا: "+r.partName+" — "+fmt(r.total)+" "+r.currency);}catch(Exception e){status.setText("لم تُحفظ الصيانة السريعة: "+msg(e));}}
 private void reset(){partId.setText("");quantity.setText("1");unitPrice.setText("");serviceFee.setText("");customerName.setText("");customerPhone.setText("");watchNote.setText("");handover.setSelection(0);for(int i=0;i<paymentSection.getChildCount();i++){View v=paymentSection.getChildAt(i);if(v.getTag() instanceof PaymentViews)((PaymentViews)v.getTag()).amount.setText("");}}
 private static String accountCode(int p){if(p==1)return "SHAM_CASH";if(p==2)return "EXTERNAL";if(p==3)return "BANK";return "MAIN";}private static final class PaymentViews{final EditText amount;final Spinner currency,account;PaymentViews(EditText a,Spinner c,Spinner ac){amount=a;currency=c;account=ac;}}
 private static EditText field(Activity a,String hint,int type){EditText e=new EditText(a);e.setHint(hint);e.setInputType(type);e.setGravity(Gravity.END);e.setMinHeight(dpStatic(a,54));e.setLayoutParams(new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));return e;}private static int numType(){return InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL;}private static int dpStatic(Activity a,int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private int dp(int v){return dpStatic(a,v);}private static double num(EditText e){String s=e.getText().toString().trim();return s.isEmpty()?0:Double.parseDouble(s);}private static String fmt(double v){return String.format(java.util.Locale.US,"%.2f",v);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}
